const GROUND: Record<string, number> = { POB: 1.7, WEL: 4.7, MBB: 5.4, NMS: 5.4, FNT: 5.4, BME: 5.4 };

export const check: BlockCheck = (scene) => {
  const { physics, RAPIER, player, plans, travel } = scene;
  const failures: string[] = [];
  const report: Record<string, unknown> = {};
  const down = { x: 0, y: -1, z: 0 };
  const top = (x: number, z: number) => {
    const h = physics.castRay(new RAPIER.Ray({ x, y: 200, z }, down), 400, true, undefined, undefined, player);
    return h ? 200 - h.timeOfImpact : null;
  };
  // 1. Roof Y vs LiDAR (same datum). Install bodies: 0.1 m; generated decks: 0.6 m.
  const roofs: unknown[] = [];
  for (const [label, x, z, want] of TARGETS) {
    const y = top(x, z), res = y === null ? null : +(y - want).toFixed(2);
    roofs.push({ label, x, z, lidarY: want, builtY: y === null ? null : +y.toFixed(2), residual: res });
    const tol = label.includes('install') ? 0.1 : 0.6;
    if (res === null || Math.abs(res) > tol) failures.push(`${label} at (${x}, ${z}): built Y ${y} vs LiDAR Y ${want}`);
  }
  report.roofs = roofs;
  // 2. Coverage inside official polygons (2 m grid, built top > LiDAR groundY + 2).
  const inRing = (x: number, z: number, r: [number, number][]) => { let c = false; for (let i = 0, j = r.length - 1; i < r.length; j = i++) { const a = r[i], b = r[j]; if ((a[1] > z) !== (b[1] > z) && x < (b[0] - a[0]) * (z - a[1]) / (b[1] - a[1]) + a[0]) c = !c; } return c; };
  const coverage: Record<string, number> = {};
  for (const [abbr, ring] of Object.entries(OFFICIAL)) {
    const xs = ring.map(p => p[0]), zs = ring.map(p => p[1]); let n = 0, built = 0;
    for (let x = Math.min(...xs) + 1; x < Math.max(...xs); x += 2) for (let z = Math.min(...zs) + 1; z < Math.max(...zs); z += 2) {
      if (!inRing(x, z, ring)) continue; n++; const y = top(x, z); if (y !== null && y > GROUND[abbr] + 2) built++;
    }
    coverage[abbr] = +(built / Math.max(1, n)).toFixed(3);
    if (coverage[abbr] < 0.88) failures.push(`${abbr}: only ${coverage[abbr]} of the official polygon has a built body (expected >= 0.88)`);
  }
  report.coverage = coverage;
  // 3. Decisions.
  const dec: Record<string, string> = {};
  for (const key of ['655081:892', '-201:add', '-202:add', '-203:add', '504518:187', '507353:224', '464607:38', '656376:923', '466248:62', '569900:511', '611143:691', '633522:815']) {
    dec[key] = plans.find((p: { building: { key?: string } }) => p.building.key === key)?.decision ?? 'missing';
  }
  report.decisions = dec;
  const want: Record<string, string> = { '-202:add': 'generated', '655081:892': 'authored', '-201:add': 'authored', '464607:38': 'generated', '656376:923': 'authored', '466248:62': 'generated', '569900:511': 'generated', '611143:691': 'generated', '633522:815': 'generated' };
  for (const [k, v] of Object.entries(want)) if (dec[k] !== v) failures.push(`record ${k} is ${dec[k]}, expected ${v}`);
  // 5. Round 2: pitched roof sections (MBB, NMS, Welch middle bar) vs the LiDAR surface itself.
  const stats = (rs: number[]) => { const a = rs.map(Math.abs).sort((m, n) => m - n); return { n: a.length, medianAbs: +(a[Math.floor(a.length / 2)] ?? NaN).toFixed(2), p90Abs: +(a[Math.floor(a.length * .9)] ?? NaN).toFixed(2), within1m: +(a.filter(v => v <= 1).length / Math.max(1, a.length)).toFixed(3) }; };
  const pitched: Record<string, ReturnType<typeof stats>> = {};
  const bySection = new Map<string, number[]>();
  for (const [id, x, z, want] of PITCHED) { const y = top(x, z); if (!bySection.has(id)) bySection.set(id, []); bySection.get(id)!.push(y === null ? 99 : y - want); }
  for (const [id, rs] of bySection) {
    pitched[id] = stats(rs);
    if (!(pitched[id].medianAbs <= 0.5) || pitched[id].within1m < 0.75) failures.push(`${id}: built roof vs LiDAR ${JSON.stringify(pitched[id])}`);
  }
  report.pitchedRoofs = pitched;
  // 6. Round 2: NHB's own heights (authored hackerman-building.ts) vs LiDAR.
  const nhb: Record<string, ReturnType<typeof stats> & { maxBuilt?: number }> = {};
  const byPart = new Map<string, { rs: number[]; ys: number[] }>();
  for (const [part, x, z, want] of NHB) { const y = top(x, z); if (!byPart.has(part)) byPart.set(part, { rs: [], ys: [] }); const e = byPart.get(part)!; e.rs.push(y === null ? 99 : y - want); e.ys.push(y ?? -1); }
  for (const [part, e] of byPart) nhb[part] = { ...stats(e.rs), maxBuilt: +Math.max(...e.ys).toFixed(2) };
  if (!(nhb['NHB penthouse']?.medianAbs <= 0.5)) failures.push(`NHB penthouse vs LiDAR: ${JSON.stringify(nhb['NHB penthouse'])}`);
  if (!(nhb['NHB west roof']?.medianAbs <= 0.3) || (nhb['NHB west roof']?.maxBuilt ?? 99) > 32.0) failures.push(`NHB west roof vs LiDAR Y31.4: ${JSON.stringify(nhb['NHB west roof'])}`);
  const open = NHB_OPEN.map(([x, z]) => ({ x, z, top: top(x, z) }));
  for (const o of open) if (o.top !== null && o.top > 20) failures.push(`NHB canopy beyond the measured edge at (${o.x}, ${o.z}): top ${o.top.toFixed(2)}`);
  report.nhb = { ...nhb, beyondCanopyEdge: open };
  // 4. Map travel lands outdoors.
  const trips: Record<string, unknown> = {};
  for (const [label, p] of [['NHB landmark', [-9.84, -150.47]], ['Welch west wing', [-100, -70]], ['POB', [57, -85]], ['FNT', [-80, -196]], ['NMS', [-40, -345]]] as [string, [number, number]][]) {
    const r = travel(p); trips[label] = r;
    if (!r.landing) failures.push(`travel to ${label}: no landing`);
    else if (r.enclosed) failures.push(`travel to ${label}: landing enclosed under a roof`);
  }
  report.travel = trips;
  // 7. D03 NMS facade (nms-detail.ts): textured brick walls, 4 green glazed bays on the south face (d03-orbit-southeast) and on the
  // north face (ut-nms-401), render rays at each bay centre hit the bay glazing first, punched windows removed inside the run,
  // pale eave band present; b02-owned maps (color + normal + roughness) on the new finishes, never shared with another owner.
  {
    const inst = scene.blocks.installs.find((x: { id: string }) => x.id === 'b02-sciences')?.install;
    const meshes = ([...(inst?.solids ?? []), ...(inst?.detail ?? [])] as THREE.Mesh[]);
    const matOf = (m: THREE.Mesh) => [m.material].flat()[0] as THREE.MeshStandardMaterial;
    const rc = new THREE.Raycaster(); rc.far = 20; const faces: Record<string, { samples: number; glass: number; first: Record<string, number> }> = {};
    for (const [face, z0, dir] of [['south', -318, 1], ['north', -372, -1]] as [string, number, number][]) {
      const f = faces[face] = { samples: 0, glass: 0, first: {} as Record<string, number> };
      for (const [xa, xb] of nmsBaySpans()) for (const y of [17, 21, 25]) {
        rc.set(new THREE.Vector3((xa + xb) / 2 + 0.2, y, z0), new THREE.Vector3(0, 0, -dir)); const h = rc.intersectObjects(meshes, false)[0]; if (!h) continue;
        f.samples++; const n = matOf(h.object as THREE.Mesh).name; f.first[n] = (f.first[n] ?? 0) + 1; if (n === 'b02 NMS green-tinted bay glazing') f.glass++;
      }
      if (f.samples < 8 || f.glass < f.samples * 0.75) failures.push(`NMS ${face} bays: ${JSON.stringify(f)}`);
    }
    const st = (inst?.stats ?? scene.blocks.stats['b02-sciences']) as { nms?: { bays: number; bayFaces: number; bandSegments: number; punchedReplaced: number } };
    const textured: Record<string, unknown> = {}; const others = new Set<THREE.Texture>(); const own = new Set(meshes);
    for (const root of [scene.walkway.surfaces, scene.world.group]) (root as THREE.Object3D).traverse(o => { const mm = (o as THREE.Mesh).material; if (!mm || own.has(o as THREE.Mesh)) return; for (const m2 of [mm].flat() as THREE.MeshStandardMaterial[]) for (const t of [m2.map, m2.normalMap, m2.roughnessMap]) if (t) others.add(t); });
    let shared = 0;
    for (const n of ['b02 NMS textured buff brick', 'b02 NMS pale stone eave band', 'b02 NMS roof plant metal']) {
      const m = meshes.map(matOf).find(mm => mm.name === n); const maps = m ? [m.map, m.normalMap, m.roughnessMap] : [];
      textured[n] = maps.map(t => !!t); for (const t of maps) if (t && others.has(t)) shared++;
      if (!m || !maps.every(Boolean)) failures.push(`${n}: missing or untextured ${JSON.stringify(textured[n])}`);
    }
    report.nmsFacade = { faces, stats: st?.nms, textured, sharedWithOtherOwners: shared, plant: { housings: NMS_DETAIL.housings.length, stacks: NMS_DETAIL.stacks.length } };
    if (shared) failures.push(`b02 textures shared with other owners: ${shared}`);
    if (!st?.nms || st.nms.bays < 8 || st.nms.bayFaces < 2 || st.nms.bandSegments < 4 || st.nms.punchedReplaced < 8) failures.push(`NMS facade stats ${JSON.stringify(st?.nms)}`);
  }
  // 8. D03 SSB rebuild (ssb.ts).
  {
    const inst = scene.blocks.installs.find((x: { id: string }) => x.id === 'b02-sciences')?.install;
    const all = ([...(inst?.solids ?? []), ...(inst?.detail ?? [])] as THREE.Mesh[]);
    const ssbMeshes = all.filter(m => m.name.startsWith('b02 SSB ')), others = all.filter(m => !m.name.startsWith('b02 SSB ')).sort((p, q) => p.name < q.name ? -1 : 1);
    const fnvA = (arrs: Float32Array[]) => { let h = 0x811c9dc5, n = 0; for (const a of arrs) { const b = new Uint8Array(a.buffer, a.byteOffset, a.byteLength); n += a.length; for (let i = 0; i < b.length; i++) { h ^= b[i]; h = Math.imul(h, 0x01000193) >>> 0; } } return { floats: n, fnv1a: h.toString(16) }; };
    // a. everything that is not SSB is byte-identical to the B01-B02 checkpoint build (NMS, POB, WEL, MBB, FNT bodies, plant, colliders).
    const cols = (inst?.colliders ?? []) as { shape: { vertices: Float32Array } }[];
    const before = fnvA(others.map(m => m.geometry.getAttribute('position').array as Float32Array)), beforeCols = fnvA(cols.slice(0, -1).map(c => c.shape.vertices));
    const preserved = { meshes: others.length, ...before, colliders: cols.length - 1, colliderFloats: beforeCols.floats, colliderFnv1a: beforeCols.fnv1a };
    if (JSON.stringify(preserved) !== JSON.stringify(PRESERVED_B02)) failures.push(`b02 non-SSB geometry changed: ${JSON.stringify(preserved)} vs ${JSON.stringify(PRESERVED_B02)}`);
    // b. replacement committed, record authored (no generated flat SSB body left)
    const committed = Object.entries((scene.blocks.replacements?.committed ?? {}) as Record<string, string>).filter(([, o]) => o === 'b02-sciences').map(([k]) => k);
    if (!committed.includes('656376:923')) failures.push('SSB replacement not committed');
    // c. roof vs the 2017 DSM (same rule as section 5), and exact planar facets on the measured roof function
    const res = SSB_DSM.map(([x, z, y]) => { const t = top(x, z); return t === null ? 99 : t - y; });
    const roofStats = stats(res);
    if (!(roofStats.medianAbs <= 0.5) || roofStats.within1m < 0.75) failures.push(`SSB roof vs DSM ${JSON.stringify(roofStats)}`);
    const ssbB = scene.world.data.buildings.find((b: { key?: string }) => b.key === '656376:923') as { rings: [number, number][][] };
    const F = ssbFrame(ssbB.rings[0]), toUV = (x: number, z: number) => [(x - F.O[0]) * F.eu[0] + (z - F.O[1]) * F.eu[1], (x - F.O[0]) * F.ev[0] + (z - F.O[1]) * F.ev[1]] as [number, number];
    let facetTris = 0, offRoof = 0; const offEx: unknown[] = []; const roofMesh = ssbMeshes.find(m => m.name.startsWith('b02 SSB solid clay tile'));
    if (roofMesh) { const pa = roofMesh.geometry.getAttribute('position'); for (let i = 0; i + 2 < pa.count; i += 3) { facetTris++; const cx = (pa.getX(i) + pa.getX(i + 1) + pa.getX(i + 2)) / 3, cy = (pa.getY(i) + pa.getY(i + 1) + pa.getY(i + 2)) / 3, cz = (pa.getZ(i) + pa.getZ(i + 1) + pa.getZ(i + 2)) / 3;
      const pts = [[pa.getX(i), pa.getY(i), pa.getZ(i)], [pa.getX(i + 1), pa.getY(i + 1), pa.getZ(i + 1)], [pa.getX(i + 2), pa.getY(i + 2), pa.getZ(i + 2)], [cx, cy, cz]];
      if (pts.some(([x, y, z]) => Math.abs(ssbRoofAt(F, ...toUV(x, z)) - y) > 0.002 && Math.abs(y - SSB.wellY) > 0.002)) { offRoof++; if (offEx.length < 4) offEx.push(pts.map(([x, y, z]) => [+x.toFixed(2), +y.toFixed(3), +z.toFixed(2), +ssbRoofAt(F, ...toUV(x, z)).toFixed(3), toUV(x, z).map(v => +v.toFixed(2))])); } } }
    if (!facetTris || offRoof) failures.push(`SSB roof: ${offRoof}/${facetTris} tile triangles off the exact measured roof surface ${JSON.stringify(offEx)}`);
    // d. the top gallery is OPEN between the piers (render AND physics rays at gallery mid-height reach the back wall), piers are
    //    physical at the facade line, and the lower storeys are closed at the facade line.
    const rc = new THREE.Raycaster(); rc.far = 14; const lines = ssbLines(ssbB.rings[0]), outline = lines.facade;
    let open = 0, openN = 0, pierHit = 0, pierN = 0, closed = 0, closedN = 0; const ex: unknown[] = [];
    const ray = (x: number, y: number, z: number, nx: number, nz: number) => { rc.set(new THREE.Vector3(x, y, z), new THREE.Vector3(-nx, 0, -nz)); const h = rc.intersectObjects(ssbMeshes.filter(m => m.name.includes(' solid ')), false)[0];
      const ph = physics.castRay(new RAPIER.Ray({ x, y, z }, { x: -nx, y: 0, z: -nz }), 14, true, undefined, undefined, player); return { r: h ? h.distance : NaN, p: ph ? ph.timeOfImpact : NaN }; };
    const area = outline.reduce((s2, p, i) => { const q2 = outline[(i + 1) % outline.length]; return s2 + p[0] * q2[1] - q2[0] * p[1]; }, 0);
    for (let i = 0; i < outline.length; i++) {
      const a = outline[i], c = outline[(i + 1) % outline.length], L = Math.hypot(c[0] - a[0], c[1] - a[1]); if (L < 8) continue;
      let nx = (c[1] - a[1]) / L, nz = -(c[0] - a[0]) / L; if (area < 0) { nx = -nx; nz = -nz; }
      // piers on the FACADE line (the edge loop the generator uses): k * L / n; mid-bay (k + 0.5) * L / n
      const n = Math.max(1, Math.round(L / SSB.bay)), bay = L / n, ux = (c[0] - a[0]) / L, uz = (c[1] - a[1]) / L;
      for (let k = 1; k < n; k++) {
        const sMid = (k + 0.5) * bay, sPier = k * bay;
        for (const [s2, kind] of [[sMid, 'mid'], [sPier, 'pier']] as [number, string][]) {
          const x = a[0] + ux * s2 + nx * 6, z = a[1] + uz * s2 + nz * 6, g = ray(x, 35.0, z, nx, nz);
          const backD = 6 + SSB.galleryDepth, facadeD = 6;
          if (kind === 'mid') { openN++; if (Math.abs(g.r - backD) < 0.2 && Math.abs(g.p - backD) < 0.2) open++; else if (ex.length < 4) ex.push(['mid', +x.toFixed(1), +z.toFixed(1), g]); }
          else { pierN++; if (Math.abs(g.r - (facadeD - SSB.pier / 2)) < 0.2 && Math.abs(g.p - g.r) < 0.05) pierHit++; else if (ex.length < 8) ex.push(['pier', +x.toFixed(1), +z.toFixed(1), g]); }
          if (kind === 'mid') { closedN++; const w = ray(x, 28.0, z, nx, nz); if (Math.abs(w.r - facadeD) < 0.2 && Math.abs(w.p - facadeD) < 0.2) closed++; }
        }
      }
    }
    if (openN < 40 || open < openN * 0.9) failures.push(`SSB gallery not open: ${open}/${openN} ${JSON.stringify(ex)}`);
    if (pierN < 40 || pierHit < pierN * 0.9) failures.push(`SSB piers: ${pierHit}/${pierN} ${JSON.stringify(ex)}`);
    if (closed < closedN * 0.95) failures.push(`SSB lower storeys not closed at the facade line: ${closed}/${closedN}`);
    // e. mapped paths within 12 m of the SSB outline: standing capsule free of SSB geometry
    const ssbCol = cols[cols.length - 1] as unknown as { handle: number }, onlySsb = (k: { handle: number }) => k.handle === ssbCol.handle;
    const capsule = new RAPIER.Capsule(0.5, 0.3); let pathS = 0; const pathBad: unknown[] = [];
    const roofLine = lines.outline, near = (x: number, z: number) => roofLine.some((p, i) => { const q2 = roofLine[(i + 1) % roofLine.length], dx = q2[0] - p[0], dz = q2[1] - p[1], l = dx * dx + dz * dz, t = Math.max(0, Math.min(1, ((x - p[0]) * dx + (z - p[1]) * dz) / l)); return Math.hypot(p[0] + t * dx - x, p[1] + t * dz - z) < 12; });
    for (const pth of scene.world.data.paths as { id: number; points: [number, number][] }[]) for (let i = 0; i + 1 < pth.points.length; i++) {
      const [a2, b2] = [pth.points[i], pth.points[i + 1]], L = Math.hypot(b2[0] - a2[0], b2[1] - a2[1]);
      for (let t = 0; t <= L; t += 1) { const x = a2[0] + (b2[0] - a2[0]) * t / L, z = a2[1] + (b2[1] - a2[1]) * t / L; if (!near(x, z)) continue;
        const gh = physics.castRay(new RAPIER.Ray({ x, y: 60, z }, down), 80, true, undefined, undefined, player, undefined, (k: { handle: number }) => !onlySsb(k)); if (!gh) continue; pathS++;
        let hit = false; physics.intersectionsWithShape({ x, y: 60 - gh.timeOfImpact + 1.1, z }, { x: 0, y: 0, z: 0, w: 1 }, capsule, () => { hit = true; return false; }, undefined, undefined, player, undefined, onlySsb);
        if (hit && pathBad.length < 5) pathBad.push([pth.id, +x.toFixed(1), +z.toFixed(1)]); } }
    if (pathBad.length) failures.push(`SSB blocks mapped paths ${JSON.stringify(pathBad)}`);
    // f. textured own finishes, nothing shared with other owners
    const others2 = new Set<THREE.Texture>(); const own = new Set(all);
    for (const root of [scene.walkway.surfaces, scene.world.group]) (root as THREE.Object3D).traverse(o => { const mm = (o as THREE.Mesh).material; if (!mm || own.has(o as THREE.Mesh)) return; for (const m2 of [mm].flat() as THREE.MeshStandardMaterial[]) for (const t of [m2.map, m2.normalMap, m2.roughnessMap]) if (t) others2.add(t); });
    const tex: Record<string, unknown> = {}; let sharedT = 0;
    for (const n2 of ['b02 SSB pale precast', 'b02 SSB clay tile roof', 'b02 SSB red brick infill']) { const m = all.map(x => [x.material].flat()[0] as THREE.MeshStandardMaterial).find(mm => mm.name === n2);
      const maps = m ? [m.map, m.normalMap, m.roughnessMap] : []; tex[n2] = maps.map(t => !!t); for (const t of maps) if (t && others2.has(t)) sharedT++; if (!m || !maps.every(Boolean)) failures.push(`${n2}: missing or untextured`); }
    if (sharedT) failures.push(`SSB textures shared with other owners: ${sharedT}`);
    report.ssb = { preserved, roofVsDsm: roofStats, facets: { triangles: facetTris, offRoof }, gallery: { open, openN, pierHit, pierN, closed, closedN, examples: ex }, paths: { samples: pathS, blocked: pathBad }, textures: tex, meshes: ssbMeshes.map(m => m.name) };
  }
  return { ok: failures.length === 0, report, failures };
};
